    "statement": "No studies were found that evaluated the effects of controlling bracken by applying herbicide and sowing seed.",
    "citations": [
      "1658"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of controlling bracken by cutting and burning.",
    "citations": [
      "1655"
    ]
  },
  {
    "statement": "One trial in Norway and a study in the UK found that cutting bracken increased the cover or biomass of heather.",
    "citations": [
      "1653"
    ]
  },
  {
    "statement": "Two other studies in the UK found cutting bracken caused no increase in heather cover or seedling abundance.",
    "citations": [
      "1653"
    ]
  },
  {
    "statement": "One UK study found that cutting bracken increased the species richness of heathland plants.",
    "citations": [
      "1653"
    ]
  },
  {
    "statement": "Another UK study found cutting bracken increased species diversity but not richness.",
    "citations": [
      "1653"
    ]
  },
  {
    "statement": "Cutting bracken was found to increase the cover of wavy hair-grass and sheep's fescue in one UK study.",
    "citations": [
      "1653"
    ]
  },
  {
    "statement": "Another UK study found cutting bracken did not increase the abundance of gorse or common cow-wheat.",
    "citations": [
      "1653"
    ]
  },
  {
    "statement": "The effect of cutting on bracken cover or biomass was mixed.",
    "citations": []
  },
  {
    "statement": "Some studies in Norway and the UK showed a reduction in bracken cover or biomass as a result of cutting.",
    "citations": []
  },
  {
    "statement": "One UK study showed mixed effects on bracken cover or biomass from cutting.",
    "citations": []
  },
  {
    "statement": "Another UK study showed no decrease in bracken abundance from cutting.",
    "citations": []
  }
]

